CREATE TABLE model_workspace(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 0,meta_json TEXT NOT NULL CHECK(json_valid(meta_json)),reference_json TEXT NOT NULL CHECK(json_valid(reference_json)));
CREATE TABLE model_versions(id TEXT PRIMARY KEY NOT NULL,service_id TEXT NOT NULL REFERENCES services(id),record_json TEXT NOT NULL CHECK(json_valid(record_json)),removed_at INTEGER);
CREATE TABLE model_validations(id TEXT PRIMARY KEY NOT NULL,version_id TEXT REFERENCES model_versions(id),record_json TEXT NOT NULL CHECK(json_valid(record_json)),removed_at INTEGER);
CREATE TABLE service_route_records(id TEXT PRIMARY KEY NOT NULL,offer_id TEXT NOT NULL REFERENCES offers(id),record_json TEXT NOT NULL CHECK(json_valid(record_json)),removed_at INTEGER);
CREATE TABLE simulation_records(kind TEXT NOT NULL,id TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),PRIMARY KEY(kind,id));
CREATE TABLE service_supply_records(id TEXT PRIMARY KEY NOT NULL,channel_model_id TEXT NOT NULL REFERENCES channel_models(id),service_id TEXT NOT NULL REFERENCES services(id),record_json TEXT NOT NULL CHECK(json_valid(record_json)),removed_at INTEGER);
UPDATE db_state SET schema_version=2 WHERE id=1;
